// Parties and the trust directory. Keys are generated by the SDK. Private
// halves stay in memory, except in tests that hand a fixture to a child
// process through a temporary file.

import { generateKeyPair } from 'agent-passport-system'

export type Role = 'principal' | 'agent' | 'gate'

export interface Party {
  id: string
  role: Role
  publicKey: string
  privateKey: string
}

export function makeParty(id: string, role: Role): Party {
  const { publicKey, privateKey } = generateKeyPair()
  return { id, role, publicKey, privateKey }
}

/** Who holds which public key, and in which role. The gate takes it as
 *  configuration. Keys that appear inside records are never trusted on
 *  their own. */
export interface TrustedKeys {
  format: 'aps-checkout-gate/trusted-keys-v1'
  parties: Record<string, { role: Role; publicKey: string }>
}

export function trustedKeys(parties: Party[]): TrustedKeys {
  const out: TrustedKeys['parties'] = {}
  for (const p of parties) out[p.id] = { role: p.role, publicKey: p.publicKey }
  return { format: 'aps-checkout-gate/trusted-keys-v1', parties: out }
}

/** The key_id convention on every signature in this sandbox. */
export function keyId(did: string): string {
  return `${did}#key-1`
}

export function keyOf(directory: TrustedKeys, id: string, role: Role): string | undefined {
  const p = directory.parties[id]
  return p && p.role === role ? p.publicKey : undefined
}
